int main(int argc, char **argv) {
  if (!parseArgs(argc, argv, gConfig))
    return 2;
  const Config &cfg = gConfig;
  setGlobals(cfg);

  CUDA_CHECK(cudaGetDevice(&gDevice));
  cudaDeviceProp prop;
  CUDA_CHECK(cudaGetDeviceProperties(&prop, gDevice));
  int concurrentManaged = 0;
  CUDA_CHECK(cudaDeviceGetAttribute(&concurrentManaged,
                                    cudaDevAttrConcurrentManagedAccess, gDevice));
  gCanPrefetch = concurrentManaged != 0;

  std::printf("kernel: ext_uaf_\ntarget: gpu_a100\n");
  std::printf("gpu: %s (sm_%d%d, device %d)\nprefetch: %s\n", prop.name,
              prop.major, prop.minor, gDevice, gCanPrefetch ? "yes" : "no");
  std::printf("size: im=%ld jm=%ld kb=%ld\nsamples: %d\n", cfg.im, cfg.jm,
              cfg.kb, cfg.samples);
  std::printf("compare: old/new bitwise, */cuda rtol=%g atol=%g\n", cfg.rtol, cfg.atol);
  printGlobals();

  // `initial` keeps the inputs; every variant runs on its own copy.
  std::vector<ManagedArray> initial = allocateSet(cfg);
  std::vector<std::vector<ManagedArray>> sets;
  for (int v = 0; v < NUM_VARIANTS; ++v)
    sets.push_back(allocateSet(cfg));
  std::vector<uint64_t> initialHash(kNumArgs);
  for (int i = 0; i < kNumArgs; ++i)
    initialHash[i] = contentHash(initial[i]);

  // Correctness run on fresh inputs.
  for (int v = 0; v < NUM_VARIANTS; ++v) {
    prefetchToDevice(sets[v]);
    callKernel(v, sets[v]);
  }

  const int kPairs[3][2] = {{OLD, NEW}, {OLD, CUDA}, {NEW, CUDA}};
  int mismatchedPairs[3] = {0, 0, 0};
  std::vector<std::string> firstMismatches;
  std::vector<bool> written(kNumArgs, false);
  int mismatchedArrays = 0;
  // mm_*: bitwise mismatches; tol_*: mismatches beyond the tolerance.
  std::printf("\n%-4s %-12s %-4s %-4s %12s %12s %12s %12s %12s %12s %12s %12s %s\n",
              "arg", "name", "type", "ext", "elements", "mm_old_new", "mm_old_cuda",
              "mm_new_cuda", "tol_old_cuda", "tol_new_cuda", "max_abs", "max_rel",
              "written");
  for (int i = 0; i < kNumArgs; ++i) {
    const ArgSpec &s = kArgs[i];
    PairDiff d[3];
    bool any = false;
    double maxAbs = 0.0, maxRel = 0.0;
    for (int p = 0; p < 3; ++p) {
      d[p] = compare(s, sets[kPairs[p][0]][i], sets[kPairs[p][1]][i], kPairs[p][1] == CUDA);
      if (d[p].failures) {
        any = true;
        ++mismatchedPairs[p];
        // Flat index split as ACC3 (i + j*im + k*im*jm).
        const size_t n = d[p].first;
        const size_t plane = static_cast<size_t>(cfg.im) * static_cast<size_t>(cfg.jm);
        const uint32_t *px = static_cast<const uint32_t *>(sets[kPairs[p][0]][i].data);
        const uint32_t *py = static_cast<const uint32_t *>(sets[kPairs[p][1]][i].data);
        char line[256];
        if (s.elem == Elem::F32) {
          float a, b;
          std::memcpy(&a, &px[n], 4);
          std::memcpy(&b, &py[n], 4);
          std::snprintf(line, sizeof line,
                        "first failure %s %s/%s: index %zu (i=%zu j=%zu k=%zu) %.9g vs %.9g",
                        s.name, kVariantNames[kPairs[p][0]], kVariantNames[kPairs[p][1]], n,
                        n % cfg.im, n % plane / cfg.im, n / plane, a, b);
        } else {
          std::snprintf(line, sizeof line, "first failure %s %s/%s: index %zu %d vs %d",
                        s.name, kVariantNames[kPairs[p][0]], kVariantNames[kPairs[p][1]], n,
                        static_cast<int>(px[n]), static_cast<int>(py[n]));
        }
        firstMismatches.push_back(line);
      }
      maxAbs = std::max(maxAbs, d[p].maxAbs);
      maxRel = std::max(maxRel, d[p].maxRel);
    }
    for (int v = 0; v < NUM_VARIANTS; ++v)
      written[i] = written[i] || contentHash(sets[v][i]) != initialHash[i];
    if (any)
      ++mismatchedArrays;
    std::printf("%-4d %-12s %-4s %-4s %12zu %12zu %12zu %12zu %12zu %12zu %12.4g %12.4g %s\n",
                i, s.name, s.elem == Elem::F32 ? "f32" : "i32",
                s.selector ? "sel" : (s.extent == Extent::E3D ? "3D" : "2D"),
                initial[i].count, d[0].mismatches, d[1].mismatches, d[2].mismatches,
                d[1].failures, d[2].failures, maxAbs, maxRel, written[i] ? "yes" : "no");
  }
  const bool pass = mismatchedArrays == 0;
  if (!firstMismatches.empty())
    std::printf("\n");
  for (const std::string &line : firstMismatches)
    std::printf("%s\n", line.c_str());
  std::printf("\nresult: %s (%d of %d arrays fail; old/new %d, old/cuda %d, "
              "new/cuda %d)\n", pass ? "PASS" : "FAIL", mismatchedArrays, kNumArgs,
              mismatchedPairs[0], mismatchedPairs[1], mismatchedPairs[2]);

  // Timing: written arrays are restored from `initial` before every call,
  // inputs stay as is. One untimed warm-up call per variant; the variant that
  // runs first rotates between samples so none always gets the warmer state.
  prefetchToDevice(initial);
  auto timedCall = [&](int v) {
    std::vector<ManagedArray> &set = sets[v];
    for (int i = 0; i < kNumArgs; ++i)
      if (written[i])
        CUDA_CHECK(cudaMemcpy(set[i].data, initial[i].data, set[i].bytes(),
                              cudaMemcpyDefault));
    prefetchToDevice(set);
    auto t0 = std::chrono::steady_clock::now();
    callKernel(v, set);
    auto t1 = std::chrono::steady_clock::now();
    return elapsedMs(t0, t1);
  };
  for (int v = 0; v < NUM_VARIANTS; ++v)
    timedCall(v);
  std::vector<double> times[NUM_VARIANTS];
  for (int s = 0; s < cfg.samples; ++s)
    for (int r = 0; r < NUM_VARIANTS; ++r) {
      const int v = (s + r) % NUM_VARIANTS;
      times[v].push_back(timedCall(v));
    }
  auto avg = [](const std::vector<double> &v) {
    double sum = 0;
    for (double x : v)
      sum += x;
    return sum / static_cast<double>(v.size());
  };
  auto minOf = [](const std::vector<double> &v) {
    return *std::min_element(v.begin(), v.end());
  };
  auto median = [](std::vector<double> v) {
    std::sort(v.begin(), v.end());
    size_t n = v.size();
    return n % 2 ? v[n / 2] : 0.5 * (v[n / 2 - 1] + v[n / 2]);
  };
  double med[NUM_VARIANTS];
  for (int v = 0; v < NUM_VARIANTS; ++v) {
    med[v] = median(times[v]);
    std::printf("time_%s_ms: median %.3f avg %.3f min %.3f\n", kVariantNames[v],
                med[v], avg(times[v]), minOf(times[v]));
  }
  const double speedup = med[NEW] > 0 ? med[OLD] / med[NEW] : 0.0;
  const double speedupVsCuda = med[NEW] > 0 ? med[CUDA] / med[NEW] : 0.0;
  std::printf("speedup_new_vs_old (median): %.3f\n", speedup);
  std::printf("speedup_new_vs_cuda (median): %.3f\n", speedupVsCuda);
  std::printf("SUMMARY kernel=ext_uaf_ status=%s mismatched_arrays=%d "
              "arrays=%d mm_old_new=%d mm_old_cuda=%d mm_new_cuda=%d "
              "old_median_ms=%.3f new_median_ms=%.3f cuda_median_ms=%.3f "
              "speedup=%.3f speedup_new_vs_cuda=%.3f\n",
              pass ? "PASS" : "FAIL", mismatchedArrays, kNumArgs,
              mismatchedPairs[0], mismatchedPairs[1], mismatchedPairs[2],
              med[OLD], med[NEW], med[CUDA], speedup, speedupVsCuda);
  return pass ? 0 : 1;
}
